function storageGet(klucz, wartoscDomyslna = null) {
  try {
    const item = localStorage.getItem(klucz);
    return item !== null ? JSON.parse(item) : wartoscDomyslna;
  } catch {
    return wartoscDomyslna;
  }
}

function storageSet(klucz, wartosc) {
  try {
    localStorage.setItem(klucz, JSON.stringify(wartosc));
  } catch (e) {
    console.warn("localStorage pelny lub niedostepny:", e.message);
  }
}

